{
  "master_id": "howard-roberts",
  "work_id": "chord-melody",
  "usage_notes": [
    {
      "chord_quality": "close-voicing",
      "function_role": "texture-contrast-against-open-voicings",
      "narrative": "Roberts prescribes close voicings as a deliberate textural device \u2014 \"very effective but not too often used, on the guitar\" \u2014 deployed specifically as contrast against open voicings: \"These can be used as texture contrast to the big sound of open voicings\" (chapter 3, p. 12). The implication is sparing use: close voicings land with more impact when they punctuate an otherwise open-voiced texture.",
      "source_principle_ids": [
        "close-voicing-as-texture-contrast"
      ],
      "source_work_id": "chord-melody",
      "references": [
        {
          "source": "chord-melody",
          "citation": "chapter 3 p. 12"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "h",
      "granularity_name": "idiom-application"
    },
    {
      "chord_quality": "close-voicing",
      "function_role": "voicing-conversion-to-open",
      "narrative": "Roberts prescribes converting any close voicing to an open voicing by octave displacement: \"Closed voiced chords can be opened up as far as your reach will permit, simply by moving one or more chordal tones up or down an octave\" (chapter 2, p. 6). This is the primary mechanism for expanding harmonic texture on guitar.",
      "source_principle_ids": [
        "close-to-open-octave-displacement"
      ],
      "source_work_id": "chord-melody",
      "references": [
        {
          "source": "chord-melody",
          "citation": "chapter 2 p. 6"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "close-voicing",
      "function_role": "block-chord-voicing-option",
      "narrative": "Roberts explicitly allows both close and open voicings within the block chord device: \"This is done by placing a full chord underneath each melody note. The chords can be either close or open voicings\" (chapter 2, p. 8). The choice of density is left to the player's ear within the block chord context.",
      "source_principle_ids": [
        "block-chord-voicing-change-per-note"
      ],
      "source_work_id": "chord-melody",
      "references": [
        {
          "source": "chord-melody",
          "citation": "chapter 2 p. 8"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "b",
