    },
    {
      "chord_quality": "dom7b9",
      "function_role": "chromatic-substitution-target-for-diminished",
      "narrative": "Roberts prescribes substituting diminished chords in place of dominant 7b9 chords to inject chromaticism: \"The E\u00b0 and Db\u00b0 chords are both functioning as A7b9, and are being used to provide some chromatic relief from the monotony of diatonic lines\" (chapter 3, p. 13). Any diminished chord whose tones overlap with the dominant 7b9 spelling is a valid substitute.",
      "source_principle_ids": [
        "diminished-for-dominant-7b9"
      ],
      "source_work_id": "chord-melody",
      "references": [
        {
          "source": "chord-melody",
          "citation": "chapter 3 p. 13"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7b9",
      "function_role": "harmonic-recontextualization-from-6th-chord",
      "narrative": "Roberts demonstrates that a chord symbol may carry dominant 7b9 function even when spelled as a 6th chord: \"The G6 in bar 3 is functioning as a dominant chord (Eb + 7b9)\" (chapter 3, p. 12). The lesson is that Roman numeral function must be read from the phrase context, not the chord symbol alone \u2014 a G6 can be the upper structure of an Eb7b9.",
      "source_principle_ids": [
        "four-voice-melodic-motion"
      ],
      "source_work_id": "chord-melody",
      "references": [
        {
          "source": "chord-melody",
          "citation": "chapter 3 p. 12"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dim7",
      "function_role": "chromatic-dominant-substitute",
      "narrative": "Roberts prescribes using diminished chords (E\u00b0, Db\u00b0) as substitutes for dominant 7b9 sounds \u2014 specifically A7b9 in the cited example \u2014 to \"provide some chromatic relief from the monotony of diatonic lines\" (chapter 3, p. 13). Roberts advises practicing this substitution in all keys with various diatonic melodies as ear training (chapter 3, p. 13).",
      "source_principle_ids": [
        "diminished-for-dominant-7b9"
      ],
      "source_work_id": "chord-melody",
      "references": [
        {
          "source": "chord-melody",
