      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dim7",
      "function_role": "chromatic-passing-chord",
      "narrative": "Beyond its dominant-substitute role, Roberts implies diminished chord shapes function as chromatic passing connective tissue between diatonic progression points \u2014 part of the broader family of altered passing chords (alongside m7+5 shapes) enumerated in chapter 3 and demonstrated in the chapter 5 solo. Chapter 3 prescribes studying these substitutions in all keys: \"It is good ear training to improvise this sort of thing in all keys, with various diatonic melodies\" (p. 13).",
      "source_principle_ids": [
        "chromatic-passing-chords"
      ],
      "source_work_id": "chord-melody",
      "references": [
        {
          "source": "chord-melody",
