      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "min7",
      "function_role": "tonic-area-substitution-for-maj9",
      "narrative": "Roberts demonstrates a specific minor 7 substitution in a block chord context: \"The Gm7 in bar 3 is being used as a substitute for Eb maj 9\" (chapter 2, p. 8). The Gm7 supplies three of the Eb maj9's upper extensions (G=3, Bb=5, D=maj7, F=9), making it a viable relative-minor upper-structure substitute in chord melody harmonization.",
      "source_principle_ids": [
        "block-chord-voicing-change-per-note"
      ],
      "source_work_id": "chord-melody",
      "references": [
