    },
    {
      "chord_quality": "min7",
      "function_role": "diatonic-passing-progression-chord",
      "narrative": "Roberts explicitly uses Am7 and Bm7 as structural diatonic chords in a passing-chord study: \"Example 35 shows the primary progression consisting of G6, Am7, Bm7, Cmaj7 (one chord per bar) being connected by the passing chords G#m7+5, Am7+5\" (chapter 3). The min7 chords anchor the diatonic skeleton that the altered passing shapes then connect.",
      "source_principle_ids": [
        "chromatic-passing-chords"
      ],
      "source_work_id": "chord-melody",
      "references": [
        {
          "source": "chord-melody",
