    },
    {
      "chord_quality": "min7",
      "function_role": "voice-leading-sustain-policy",
      "narrative": "Roberts's universal sustain rule applies to all chord qualities including min7: \"Sustain each chordal tone for as long as possible. In general, this means to keep your fingers in place until it's absolutely necessary to move them. This will contribute measurably to the continuity of your chord melody style\" (chapter 3, p. 15). For min7, this means the root, minor third, fifth, and seventh should each ring through into the next chord event until finger movement is forced.",
      "source_principle_ids": [
        "sustain-delay-finger-movement"
      ],
      "source_work_id": "chord-melody",
      "references": [
