      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "maj7",
      "function_role": "color-tone-addition-policy",
      "narrative": "Roberts explicitly names the major seventh as the first example of an extension that \"only affect the color and texture of the chord and do not change its scale function or its role in the progression\" (chapter 4, p. 36). The arranger should therefore feel free to reach for maj7 voicings wherever a major chord appears in the progression without disrupting harmonic identity.",
      "source_principle_ids": [
        "extensions-as-color-only"
      ],
      "source_work_id": "chord-melody",
      "references": [
