    },
    {
      "chord_quality": "maj7",
      "function_role": "diatonic-structural-chord-in-passing-study",
      "narrative": "Roberts uses Cmaj7 as one of the four structural diatonic anchor chords in the chapter 3 passing-chord study: \"the primary progression consisting of G6, Am7, Bm7, Cmaj7 (one chord per bar) being connected by the passing chords G#m7+5, Am7+5\" (chapter 3, p. 11). Cmaj7 sits at the IV position in G major and is treated as a stable harmonic target, not a passing shape.",
      "source_principle_ids": [
        "chromatic-passing-chords"
      ],
      "source_work_id": "chord-melody",
