    },
    {
      "chord_quality": "6",
      "function_role": "diatonic-structural-chord-in-passing-study",
      "narrative": "Roberts uses G6 as the tonic anchor of the chapter 3 diatonic passing-chord example: \"the primary progression consisting of G6, Am7, Bm7, Cmaj7 (one chord per bar)\" (chapter 3, p. 11). G6 functions as I in G major, confirming the 6th voicing as a fully valid tonic chord quality in Roberts's harmonic vocabulary.",
      "source_principle_ids": [
        "extensions-as-color-only"
      ],
      "source_work_id": "chord-melody",
