    },
    {
      "chord_quality": "any",
      "function_role": "chromatic-melody-harmonization-policy",
      "narrative": "Roberts prescribes a permissive rule for harmonizing chromatic melody notes against any chord quality: \"Any chromatic note within finger range can always be harmonized with a given chord form, although it may occasionally be dissonant\" (chapter 4, p. 38). When melody and harmony move independently, \"interesting extensions\" emerge from the friction (chapter 4, p. 40).",
      "source_principle_ids": [
        "chromatic-passing-chords"
      ],
      "source_work_id": "chord-melody",
