      "granularity_name": "color-tone-policy"
    },
    {
      "chord_quality": "any",
      "function_role": "low-register-voicing-floor-constraint",
      "narrative": "Roberts states a hard physical constraint applying to all chord qualities: \"if the melody note is placed too low on the staff, you will not have enough strings left to form a satisfactory chord beneath it\" and the floor is explicit \u2014 \"as low as the 4th string but no lower\" (chapter 4, p. 36). When the melody falls below this floor, Roberts prescribes jumping the melody up an octave rather than compromising the voicing.",
      "source_principle_ids": [
        "fourth-string-density-floor",
        "octave-jump-for-register"
      ],
      "source_work_id": "chord-melody",
      "references": [
